const isLink = (p.key === 'linkComponente' || p === componentProp) && /^https?:///.test(String(linkUrl || ''));
const linkHref = p.key === 'linkComponente' ? p.value : linkUrl;
const valueHtml = isLink
? `

(function () {
function renderA11yCategoryPickerBadges() {
if (typeof A11Y_CATEGORIES === 'undefined' || typeof renderA11yCategoryBadgeSvg === 'undefined') return;
document.querySelectorAll('.a11y-cat-badge-picker[data-a11y-cat]').forEach(function (el) {
var catKey = el.getAttribute('data-a11y-cat');
if (!A11Y_CATEGORIES[catKey]) return;
el.innerHTML = renderA11yCategoryBadgeSvg(catKey, 18);
});
}

function attachObserver() {
var modal = document.getElementById('a11y-category-picker-modal');
if (!modal) return;
var observer = new MutationObserver(function () {
if (!modal.classList.contains('hidden')) renderA11yCategoryPickerBadges();
});
observer.observe(modal, { attributes: true, attributeFilter: ['class'] });
}

if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', attachObserver);
} else {
attachObserver();
}
})();

(function () {
function renderA11yCategoriesHelpBadges() {
if (typeof A11Y_CATEGORIES === 'undefined' || typeof renderA11yCategoryBadgeSvg === 'undefined') return; // defensivo — nunca deveria faltar quando o modal já pode ser aberto
document.querySelectorAll('.a11y-cat-badge[data-a11y-cat]').forEach(function (el) {
var catKey = el.getAttribute('data-a11y-cat');
if (!A11Y_CATEGORIES[catKey]) return;
// Forma real da categoria (círculo/estrela/quadrado) via SVG puro —
// substitui o antigo círculo com borda + ícone Lucide. A borda/cor
// inline não é mais necessária aqui (a cor já vem preenchida no SVG).
el.style.borderColor = 'transparent';
el.innerHTML = renderA11yCategoryBadgeSvg(catKey, 28);
});
}

function attachObserver() {
var modal = document.getElementById('a11y-categories-help-modal');
if (!modal) return;
var observer = new MutationObserver(function () {
if (!modal.classList.contains('hidden')) renderA11yCategoriesHelpBadges();
});
observer.observe(modal, { attributes: true, attributeFilter: ['class'] });
}

// Guard pros dois casos possíveis: script avaliado durante o parsing
// (documento ainda "loading", caso normal aqui) ou já carregado por algum
// motivo — nunca perde o attach por causa de timing de DOMContentLoaded.
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', attachObserver);
} else {
attachObserver();
}
})();
